function formError(form, error) { let el = form.querySelector('.form-error'); if (!el) { el = document.createElement('div'); el.className = 'form-error'; el.setAttribute('role','alert'); form.prepend(el); } el.textContent = errorMessage(error); if (/(?:COMPANY|PILOT_OWNER)_CONTEXT_CHANGED_PREPARE_FRESH_WORK/.test(error.message || '')) { form.dataset.contextBlocked='true';form.querySelectorAll('button[type=submit],button[data-action=approve],button[data-action=outcome],button[data-action=review-start]').forEach(b=>b.disabled=true); const next=document.createElement('button');next.type='button';next.className='button secondary small';next.dataset.action='plan';next.textContent='Prepare fresh work';el.append(document.createElement('br'),next); } if (/ARTIFACT|TASK_OWN_DELIVERABLE_REQUIRED|REVIEW_SESSION_STALE/.test(error.message || '')) { const refreshButton = document.createElement('button'); refreshButton.type = 'button'; refreshButton.className = 'button secondary small'; refreshButton.dataset.action = 'refresh-artifact'; refreshButton.textContent = 'Refresh this review'; el.append(document.createElement('br'),refreshButton); } el.scrollIntoView({block:'nearest'}); }
